        private static ConfigurationOptions GetRedisOptions()
        {
            var options = new ConfigurationOptions { AbortOnConnectFail = true };
            var url = Environment.GetEnvironmentVariable("REDIS_URL");
            if (string.IsNullOrEmpty(url))
            {
                options.EndPoints.Add("redis", 6379);
                return options;
            }

            var uri = new Uri(url);
            options.EndPoints.Add(uri.Host, uri.IsDefaultPort || uri.Port <= 0 ? 6379 : uri.Port);
