            if (userInfo.Length > 1 && userInfo[1].Length > 0)
            {
                // Password-only AUTH authenticates as the "default" user.
                options.Password = Uri.UnescapeDataString(userInfo[1]);
            }
            options.Ssl = uri.Scheme == "rediss";
